// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport androidx.annotation.VisibleForTestingimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.common.CorrelationId/** * NOUS — Built-in agentic tools. * * These tools ship with the app and are registered in [AgenticToolRegistry] * at app startup. They cover common agentic use cases: *   - Recall a memory (offline) *   - Search the web (online) *   - Fetch a URL (online) *   - Compute a calculation (offline) * * ## Adding New Built-in Tools * * When a new tool is needed: *   1. Add a class implementing [AgenticTool] in this file *   2. Add it to [ALL] list *   3. Add tests for it * * ## User-Added Tools * * Users cannot add custom tools directly (unlike cloud providers / local LLM * models). However, every [com.roshan.persona.brain.skill.BrainSkill] is * automatically exposed as a tool via [SkillAsToolAdapter] (Module 9 wires * this). So users adding custom JS skills (Module 13) effectively add new * tools. * * @see <a href="docs/spec/module2-spec-review.pdf">§9.3.2 Built-in Tools</a> */object BuiltInAgenticTools {    /**     * Recall a memory from the memory subsystem.     *     * Wraps [com.roshan.persona.brain.memory.MemoryInterface.recall] for     * agentic use. Offline (memory is on-device).     */    class RecallMemoryTool(        private val memoryInterface: com.roshan.persona.brain.memory.MemoryInterface?,    ) : AgenticTool {        override val id: String = "recall_memory"        override val displayName: String = "Recall Memory"        override val description: String = "Recall relevant memories from the user's history. Use when you need context about past interactions or user preferences."        override val paramSchema: List<ToolParam> = listOf(            ToolParam(                name = "query",                description = "What to search for in memories",                required = true,                example = "user's mother's name",            ),            ToolParam(                name = "k",                description = "Max number of memories to return (default 5)",                required = false,                example = "3",            ),        )        override val requiresNetwork: Boolean = false        override suspend fun execute(            params: Map<String, String>,            context: BrainContext,        ): AgenticStepResult {            val startNanos = System.nanoTime()            val query = params["query"] ?: return AgenticStepResult.ToolFailure(                toolId = id,                error = "Missing required parameter: query",                retryable = false,                correlationId = context.correlationId,                durationMs = durationMs(startNanos),            )            if (memoryInterface == null) {                return AgenticStepResult.ToolFailure(                    toolId = id,                    error = "Memory subsystem not available",                    retryable = false,                    correlationId = context.correlationId,                    durationMs = durationMs(startNanos),                )            }            val k = params["k"]?.toIntOrNull() ?: 5            return when (val result = memoryInterface.recall(query, k)) {                is com.roshan.persona.common.Result.Success -> {                    val memories = result.data                    val output = if (memories.isEmpty()) {                        "No memories found for: $query"                    } else {                        memories.joinToString("\n") { mem ->                            "[${mem.type.name.lowercase()}] ${mem.content}"                        }                    }                    AgenticStepResult.ToolSuccess(                        toolId = id,                        output = output,                        data = mapOf("count" to memories.size),                        correlationId = context.correlationId,                        durationMs = durationMs(startNanos),                    )                }                is com.roshan.persona.common.Result.Failure -> AgenticStepResult.ToolFailure(                    toolId = id,                    error = result.error.message,                    retryable = result.error.retryable,                    correlationId = context.correlationId,                    durationMs = durationMs(startNanos),                )                is com.roshan.persona.common.Result.Partial -> {                    val memories = result.data                    val output = memories.joinToString("\n") { mem ->                        "[${mem.type.name.lowercase()}] ${mem.content}"                    }                    AgenticStepResult.ToolSuccess(                        toolId = id,                        output = output,                        data = mapOf("count" to memories.size),                        correlationId = context.correlationId,                        durationMs = durationMs(startNanos),                    )                }            }        }        private fun durationMs(startNanos: Long): Long =            (System.nanoTime() - startNanos) / 1_000_000    }    /**     * Test-only web search tool — returns a placeholder failure.     *     * **NOT used in production.** The real [WebSearchTool] is provided by     * `:feature:connectivity` (`com.roshan.persona.connectivity.tools.WebSearchTool`)     * and wired into the [AgenticToolRegistry] via Hilt `@Binds @IntoSet`     * multibinding in `ConnectivityToolsModule`. That real impl uses OkHttp     * + DuckDuckGo Instant Answer API to actually fetch search results.     *     * This test-only variant exists solely so [AgenticOrchestratorTest]     * (which has no network access) can verify the orchestrator's offline-     * tool-routing logic without standing up a real HTTP client. Marked     * `@VisibleForTesting` so it's never accidentally bound in production.     */    @VisibleForTesting    class WebSearchTool : AgenticTool {        override val id: String = "search_web"        override val displayName: String = "Search Web"        override val description: String = "Search the web for a query. Use when you need current information or facts you don't know."        override val paramSchema: List<ToolParam> = listOf(            ToolParam(                name = "query",                description = "The search query",                required = true,                example = "latest AI news",            ),        )        override val requiresNetwork: Boolean = true        override suspend fun execute(            params: Map<String, String>,            context: BrainContext,        ): AgenticStepResult {            // Test-only placeholder — real impl is in :feature:connectivity            // (:feature:connectivity/tools/WebSearchAndFetchTools.kt) and is            // wired via Hilt multibinding. This class exists only so the            // orchestrator tests can exercise offline-tool-routing without            // a network connection.            return AgenticStepResult.ToolFailure(                toolId = id,                error = "Web search not yet implemented (ships in Module 11)",                retryable = false,                correlationId = context.correlationId,                durationMs = 0L,            )        }    }    /**     * Test-only URL fetch tool — returns a placeholder failure.     *     * **NOT used in production.** The real [FetchUrlTool] is provided by     * `:feature:connectivity` (`com.roshan.persona.connectivity.tools.FetchUrlTool`)     * and wired into the [AgenticToolRegistry] via Hilt multibinding. That     * real impl uses OkHttp to fetch HTTPS URLs and strips HTML tags.     *     * Same rationale as [WebSearchTool]: kept as a test-only class so     * [AgenticOrchestratorTest] can verify offline-tool routing.     */    @VisibleForTesting    class FetchUrlTool : AgenticTool {        override val id: String = "fetch_url"        override val displayName: String = "Fetch URL"        override val description: String = "Fetch a web page and return its text content. Use after search_web to read a specific result."        override val paramSchema: List<ToolParam> = listOf(            ToolParam(                name = "url",                description = "The URL to fetch (must be HTTPS)",                required = true,                example = "https://example.com/article",            ),        )        override val requiresNetwork: Boolean = true        override suspend fun execute(            params: Map<String, String>,            context: BrainContext,        ): AgenticStepResult {            return AgenticStepResult.ToolFailure(                toolId = id,                error = "URL fetch not yet implemented (ships in Module 11)",                retryable = false,                correlationId = context.correlationId,                durationMs = 0L,            )        }    }    /**     * Compute a mathematical calculation.     *     * Offline — evaluates simple arithmetic expressions safely (no eval(),     * uses a restricted parser). Supports +, -, *, /, parentheses, decimals.     */    class CalculateTool : AgenticTool {        override val id: String = "calculate"        override val displayName: String = "Calculate"        override val description: String = "Compute a mathematical expression. Supports +, -, *, /, parentheses, decimals."        override val paramSchema: List<ToolParam> = listOf(            ToolParam(                name = "expression",                description = "The math expression to evaluate",                required = true,                example = "2 + 3 * 4",            ),        )        override val requiresNetwork: Boolean = false        override suspend fun execute(            params: Map<String, String>,            context: BrainContext,        ): AgenticStepResult {            val startNanos = System.nanoTime()            val expr = params["expression"] ?: return AgenticStepResult.ToolFailure(                toolId = id,                error = "Missing required parameter: expression",                retryable = false,                correlationId = context.correlationId,                durationMs = durationMs(startNanos),            )            return try {                val result = safeEval(expr)                AgenticStepResult.ToolSuccess(                    toolId = id,                    output = "$expr = $result",                    data = mapOf("result" to result.toString()),                    correlationId = context.correlationId,                    durationMs = durationMs(startNanos),                )            } catch (e: Exception) {                AgenticStepResult.ToolFailure(                    toolId = id,                    error = "Invalid expression: ${e.message}",                    retryable = false,                    correlationId = context.correlationId,                    durationMs = durationMs(startNanos),                )            }        }        /**         * Safe arithmetic evaluator — only digits, operators, parens, decimals.         * Rejects anything else (no code injection possible).         */        private fun safeEval(expr: String): Double {            // Validate: only allowed chars            val allowed = Regex("^[\\d+\\-*/.() ]+$")            if (!allowed.matches(expr)) {                throw IllegalArgumentException("Expression contains invalid characters")            }            // Use javax.script? No — not available on Android. Manual recursive descent.            return Parser(expr.trim()).parseExpression()        }        private fun durationMs(startNanos: Long): Long =            (System.nanoTime() - startNanos) / 1_000_000    }    /**     * All built-in tools that DON'T require network (in display order).     *     * WebSearchTool and FetchUrlTool are NOT included here — they're provided     * by :feature:connectivity via Hilt multibinding (real implementations     * that make actual HTTP calls, not placeholder failures).     *     * Tests that need offline WebSearchTool/FetchUrlTool can instantiate     * them directly: `BuiltInAgenticTools.WebSearchTool()`.     */    fun ALL(memoryInterface: com.roshan.persona.brain.memory.MemoryInterface?): List<AgenticTool> = listOf(        RecallMemoryTool(memoryInterface),        CalculateTool(),    )}/** * Minimal recursive descent parser for safe arithmetic. * * Grammar: *   expression = term (("+" | "-") term)* *   term       = factor (("*" | "/") factor)* *   factor     = number | "(" expression ")" | ("+" | "-") factor */private class Parser(private val input: String) {    private var pos = 0    fun parseExpression(): Double {        var result = parseTerm()        while (peek() == '+' || peek() == '-') {            val op = consume()            val right = parseTerm()            result = if (op == '+') result + right else result - right        }        return result    }    private fun parseTerm(): Double {        var result = parseFactor()        while (peek() == '*' || peek() == '/') {            val op = consume()            val right = parseFactor()            result = if (op == '*') result * right else {                if (right == 0.0) throw IllegalArgumentException("Division by zero")                result / right            }        }        return result    }    private fun parseFactor(): Double {        skipWhitespace()        return when {            peek() == '(' -> {                consume()  // (                val result = parseExpression()                if (peek() != ')') throw IllegalArgumentException("Expected )")                consume()  // )                result            }            peek() == '+' -> { consume(); parseFactor() }            peek() == '-' -> { consume(); -parseFactor() }            else -> parseNumber()        }    }    private fun parseNumber(): Double {        skipWhitespace()        val start = pos        while (pos < input.length && (input[pos].isDigit() || input[pos] == '.')) {            pos++        }        if (start == pos) throw IllegalArgumentException("Expected number")        return input.substring(start, pos).toDouble()    }    private fun peek(): Char = if (pos < input.length) input[pos] else '\u0000'    private fun consume(): Char {        skipWhitespace()        if (pos >= input.length) throw IllegalArgumentException("Unexpected end of input")        return input[pos++]    }    private fun skipWhitespace() {        while (pos < input.length && input[pos].isWhitespace()) pos++    }}